24	func cleanLongDescription(ctx context.Context) string {
25		description := `Clean up Entire session data for the current HEAD commit.
26	
27	By default, cleans session state and shadow branches for the current HEAD:
28	  - Session state files (.git/entire-sessions/<session-id>.json)
29	  - Shadow branch (entire/<commit-hash>-<worktree-hash>)
30	
31	Use --all to clean all Entire session data across the repository:
32	  - All session state files (.git/entire-sessions/)
33	  - All shadow branches
34	  - Temporary files (.entire/tmp/)`
35	
36		s, err := settings.Load(ctx)
37		if err == nil && s.IsCheckpointsV2Enabled() {
38			description += fmt.Sprintf(`
39	  - Archived v2 full transcripts older than the configured %d-day retention window`, s.GetFullTranscriptGenerationRetentionDays())
40		}
41	
42		description += `
43	
44	Use --session <id> to clean a specific session only.
45	
46	Without --force, prompts for confirmation before deleting.
47	Use --dry-run to preview what would be deleted without prompting.`
48	
49		return description
50	}
