52	func newCleanCmd() *cobra.Command {
53		var forceFlag bool
54		var allFlag bool
55		var dryRunFlag bool
56		var sessionFlag string
57	
58		cmd := &cobra.Command{
59			Use:   "clean",
60			Short: "Clean up Entire session data",
61			Long:  cleanLongDescription(context.Background()),
62			RunE: func(cmd *cobra.Command, _ []string) error {
63				ctx := cmd.Context()
64	
65				// Validate mutually exclusive flags
66				if allFlag && sessionFlag != "" {
67					return errors.New("--all and --session cannot be used together")
68				}
69	
70				// Check if in git repository before initializing logging,
71				// to avoid creating .entire/logs in arbitrary directories.
72				if _, err := paths.WorktreeRoot(ctx); err != nil {
73					return errors.New("not a git repository")
74				}
75	
76				// Initialize logging
77				logging.SetLogLevelGetter(GetLogLevel)
78				if err := logging.Init(ctx, ""); err == nil {
79					defer logging.Close()
80				}
81	
82				if allFlag {
83					return runCleanAll(ctx, cmd, forceFlag, dryRunFlag)
84				}
85	
86				if sessionFlag != "" {
87					strat := GetStrategy(ctx)
88					return runCleanSession(ctx, cmd, strat, sessionFlag, forceFlag, dryRunFlag, "Clean", "cleaned")
89				}
90	
91				return runCleanCurrentHead(ctx, cmd, forceFlag, dryRunFlag)
92			},
93		}
94	
95		cmd.Flags().BoolVarP(&forceFlag, "force", "f", false, "Skip confirmation prompt and override active session guard")
96		cmd.Flags().BoolVarP(&allFlag, "all", "a", false, "Clean all session data across the repository")
97		cmd.Flags().BoolVarP(&dryRunFlag, "dry-run", "d", false, "Preview what would be deleted without deleting")
98		cmd.Flags().StringVar(&sessionFlag, "session", "", "Clean a specific session by ID")
99	
100		return cmd
101	}
