103	// runCleanCurrentHead cleans session data for the current HEAD commit.
104	func runCleanCurrentHead(ctx context.Context, cmd *cobra.Command, force, dryRun bool) error {
105		strat := GetStrategy(ctx)
106		w := cmd.OutOrStdout()
107	
108		// Dry-run: show what would be cleaned
109		if dryRun {
110			return previewCurrentHead(ctx, w)
111		}
112	
113		// Check for active sessions before cleaning
114		if !force {
115			activeSessions, err := activeSessionsOnCurrentHead(ctx)
116			if err != nil {
117				fmt.Fprintf(cmd.ErrOrStderr(), "Warning: could not check for active sessions: %v\n", err)
118				fmt.Fprintln(cmd.ErrOrStderr(), "Use --force to override.")
119				return nil
120			}
121			if len(activeSessions) > 0 {
122				fmt.Fprintln(cmd.ErrOrStderr(), "Active sessions detected on current HEAD:")
123				for _, s := range activeSessions {
124					fmt.Fprintf(cmd.ErrOrStderr(), "  %s (phase: %s)\n", s.SessionID, s.Phase)
125				}
126				fmt.Fprintln(cmd.ErrOrStderr(), "Use --force to override or wait for sessions to finish.")
127				return nil
128			}
129		}
130	
131		// Prompt for confirmation
132		if !force {
133			var confirmed bool
134	
135			form := NewAccessibleForm(
136				huh.NewGroup(
137					huh.NewConfirm().
138						Title("Clean session data for current HEAD?").
139						Value(&confirmed),
140				),
141			)
142	
143			if err := form.Run(); err != nil {
144				if errors.Is(err, huh.ErrUserAborted) {
145					return nil
146				}
147				return fmt.Errorf("failed to get confirmation: %w", err)
148			}
149	
150			if !confirmed {
151				return nil
152			}
153		}
154	
155		if err := strat.Reset(ctx, cmd.OutOrStdout(), cmd.ErrOrStderr()); err != nil {
156			return fmt.Errorf("clean failed: %w", err)
157		}
158	
159		return nil
160	}
