162	// previewCurrentHead shows what would be cleaned for the current HEAD.
163	func previewCurrentHead(ctx context.Context, w io.Writer) error {
164		repo, err := openRepository(ctx)
165		if err != nil {
166			return err
167		}
168	
169		head, err := repo.Head()
170		if err != nil {
171			return fmt.Errorf("failed to get HEAD: %w", err)
172		}
173	
174		worktreePath, err := paths.WorktreeRoot(ctx)
175		if err != nil {
176			return fmt.Errorf("failed to get worktree path: %w", err)
177		}
178		worktreeID, err := paths.GetWorktreeID(worktreePath)
179		if err != nil {
180			return fmt.Errorf("failed to get worktree ID: %w", err)
181		}
182	
183		shadowBranchName := checkpoint.ShadowBranchNameForCommit(head.Hash().String(), worktreeID)
184	
185		// Check if shadow branch exists
186		refName := plumbing.NewBranchReferenceName(shadowBranchName)
187		_, refErr := repo.Reference(refName, true)
188		hasShadowBranch := refErr == nil
189	
190		// Find sessions for this commit
191		strat := GetStrategy(ctx)
192		sessions, err := strat.FindSessionsForCommit(ctx, head.Hash().String())
193		if err != nil {
194			sessions = nil
195		}
196	
197		if !hasShadowBranch && len(sessions) == 0 {
198			fmt.Fprintln(w, "Nothing to clean for current HEAD.")
199			return nil
200		}
201	
202		fmt.Fprint(w, "Would clean the following items:\n\n")
203	
204		if len(sessions) > 0 {
205			fmt.Fprintf(w, "Session states (%d):\n", len(sessions))
206			for _, s := range sessions {
207				fmt.Fprintf(w, "  %s (checkpoints: %d)\n", s.SessionID, s.StepCount)
208			}
209			fmt.Fprintln(w)
210		}
211	
212		if hasShadowBranch {
213			fmt.Fprintf(w, "Shadow branch:\n  %s\n\n", shadowBranchName)
214		}
215	
216		fmt.Fprintln(w, "Run without --dry-run to clean these items.")
217		return nil
218	}
