220	// runCleanSession handles the --session flag: clean/reset a single session.
221	// actionVerb is the capitalized verb (e.g., "Clean" or "Reset") and pastVerb
222	// is the past tense (e.g., "cleaned" or "reset") used in user-facing messages.
223	func runCleanSession(ctx context.Context, cmd *cobra.Command, strat *strategy.ManualCommitStrategy, sessionID string, force, dryRun bool, actionVerb, pastVerb string) error {
224		// Verify the session exists
225		state, err := strategy.LoadSessionState(ctx, sessionID)
226		if err != nil {
227			return fmt.Errorf("failed to load session: %w", err)
228		}
229		if state == nil {
230			return fmt.Errorf("session not found: %s", sessionID)
231		}
232	
233		if dryRun {
234			w := cmd.OutOrStdout()
235			fmt.Fprintf(w, "Would %s session %s (phase: %s, checkpoints: %d)\n", strings.ToLower(actionVerb), sessionID, state.Phase, state.StepCount)
236			return nil
237		}
238	
239		if !force {
240			var confirmed bool
241	
242			title := fmt.Sprintf("%s session %s?", actionVerb, sessionID)
243			description := fmt.Sprintf("Phase: %s, Checkpoints: %d", state.Phase, state.StepCount)
244	
245			form := NewAccessibleForm(
246				huh.NewGroup(
247					huh.NewConfirm().
248						Title(title).
249						Description(description).
250						Value(&confirmed),
251				),
252			)
253	
254			if err := form.Run(); err != nil {
255				if errors.Is(err, huh.ErrUserAborted) {
256					return nil
257				}
258				return fmt.Errorf("failed to get confirmation: %w", err)
259			}
260	
261			if !confirmed {
262				return nil
263			}
264		}
265	
266		if err := strat.ResetSession(ctx, cmd.OutOrStdout(), cmd.ErrOrStderr(), sessionID); err != nil {
267			return fmt.Errorf("%s session failed: %w", strings.ToLower(actionVerb), err)
268		}
269	
270		fmt.Fprintf(cmd.OutOrStdout(), "Session %s has been %s. File changes remain in the working directory.\n", sessionID, pastVerb)
271		return nil
272	}
