274	// runCleanAll cleans all session data across the repository.
275	func runCleanAll(ctx context.Context, cmd *cobra.Command, force, dryRun bool) error {
276		s, err := settings.Load(ctx)
277		if err != nil {
278			fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to load settings: %v\n", err)
279			s = &settings.EntireSettings{}
280		}
281	
282		// Scoped escape hatch for the v2 enumeration path. The fast path is
283		// near-instantaneous, but a generation whose generation.json is missing
284		// falls back to a go-git tree walk that doesn't honor context
285		// cancellation, so a single Ctrl-C can leave the user stuck. A second
286		// Ctrl-C forces exit. Scoped to clean --all only.
287		stopEscape := installForceExitOnSecondSignal(ctx)
288		defer stopEscape()
289	
290		v2Ctx, cancelV2 := context.WithCancel(ctx)
291		defer cancelV2()
292	
293		var (
294			v2Items    []strategy.CleanupItem
295			v2Warnings []string
296			v2Err      error
297		)
298		v2Done := make(chan struct{})
299		if s.IsCheckpointsV2Enabled() {
300			go func() {
301				defer close(v2Done)
302				v2Items, v2Warnings, v2Err = strategy.ListEligibleV2Generations(v2Ctx, s)
303			}()
304		} else {
305			close(v2Done)
306		}
307	
308		// List all items (sessions, shadow branches) — not just orphaned ones
309		items, err := strategy.ListAllItems(ctx)
310		if err != nil {
311			cancelV2()
312			<-v2Done
313			return fmt.Errorf("failed to list items: %w", err)
314		}
315	
316		// List temp files — skip active-session filter since --all deletes those sessions
317		tempFiles, err := listAllTempFiles(ctx)
318		if err != nil {
319			// Non-fatal: continue with other cleanup items
320			fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to list temp files: %v\n", err)
321		}
322	
323		<-v2Done
324		if v2Err != nil {
325			if errors.Is(v2Err, context.Canceled) {
326				return NewSilentError(v2Err)
327			}
328			return fmt.Errorf("failed to list v2 generations: %w", v2Err)
329		}
330		items = append(items, v2Items...)
331		for _, warning := range v2Warnings {
332			fmt.Fprintf(cmd.ErrOrStderr(), "Warning: %s\n", warning)
333		}
334	
335		return runCleanAllWithItems(ctx, cmd, force, dryRun, items, tempFiles)
336	}
337	
338	// installForceExitOnSecondSignal arms a goroutine that exits the process with
339	// code 130 if the user presses Ctrl-C twice while this scope is active. The
340	// first signal continues to be handled by the top-level cancel() in main.go.
341	// Buffer size 2 so a fast second press isn't dropped by signal.Notify.
342	// Returns a stop function that the caller MUST defer.
343	func installForceExitOnSecondSignal(ctx context.Context) func() {
344		sigCh := make(chan os.Signal, 2)
345		signal.Notify(sigCh, os.Interrupt)
346		stopCtx, stop := context.WithCancel(ctx)
347		go func() {
348			for range 2 {
349				select {
350				case <-sigCh:
351				case <-stopCtx.Done():
352					return
353				}
354			}
355			os.Exit(130)
356		}()
357		return func() {
358			signal.Stop(sigCh)
359			stop()
360		}
361	}
362	
363	// printSection prints a titled list of items if the slice is non-empty.
364	func printSection(w io.Writer, title string, items []string) {
365		if len(items) == 0 {
366			return
367		}
368		fmt.Fprintf(w, "%s (%d):\n", title, len(items))
369		for _, item := range items {
370			fmt.Fprintf(w, "  %s\n", item)
371		}
372		fmt.Fprintln(w)
373	}
374	
375	// printResultSection prints a titled list with a leading newline, for post-deletion output.
376	func printResultSection(w io.Writer, title string, items []string) {
377		if len(items) == 0 {
378			return
379		}
380		fmt.Fprintf(w, "\n%s (%d):\n", title, len(items))
381		for _, item := range items {
382			fmt.Fprintf(w, "  %s\n", item)
383		}
384	}
385	
386	// runCleanAllWithItems is the core logic for cleaning all items.
387	// Separated for testability — tests pass a cmd without a TTY and use force or dryRun to avoid prompts.
388	func runCleanAllWithItems(ctx context.Context, cmd *cobra.Command, force, dryRun bool, items []strategy.CleanupItem, tempFiles []string) error {
389		w := cmd.OutOrStdout()
390		errW := cmd.ErrOrStderr()
391		// Handle no items case
392		if len(items) == 0 && len(tempFiles) == 0 {
393			fmt.Fprintln(w, "No items to clean up.")
394			return nil
395		}
396	
397		// Group items by type for display
398		var branches, states, checkpoints, v2Generations []strategy.CleanupItem
399		for _, item := range items {
400			switch item.Type {
401			case strategy.CleanupTypeShadowBranch:
402				branches = append(branches, item)
403			case strategy.CleanupTypeSessionState:
404				states = append(states, item)
405			case strategy.CleanupTypeCheckpoint:
406				checkpoints = append(checkpoints, item)
407			case strategy.CleanupTypeV2Generation:
408				v2Generations = append(v2Generations, item)
409			}
410		}
411	
412		// Show preview when not in force mode
413		if !force || dryRun {
414			totalItems := len(items) + len(tempFiles)
415			fmt.Fprintf(w, "Found %d %s to clean:\n\n", totalItems, itemWord(totalItems))
416	
417			printSection(w, "Shadow branches", cleanupItemIDs(branches))
418			printSection(w, "Session states", cleanupItemIDs(states))
419			printSection(w, "Checkpoint metadata", cleanupItemIDs(checkpoints))
420			printSection(w, "Archived v2 generations", cleanupItemIDs(v2Generations))
421			printSection(w, "Temp files", tempFiles)
422	
423			if dryRun {
424				fmt.Fprintln(w, "Run without --dry-run to delete these items.")
425				return nil
426			}
427	
428			// Prompt for confirmation
429			var confirmed bool
430			form := NewAccessibleForm(
431				huh.NewGroup(
432					huh.NewConfirm().
433						Title(fmt.Sprintf("Delete %d %s?", totalItems, itemWord(totalItems))).
434						Value(&confirmed),
435				),
436			)
437			if err := form.Run(); err != nil {
438				if errors.Is(err, huh.ErrUserAborted) {
439					return nil
440				}
441				return fmt.Errorf("failed to get confirmation: %w", err)
442			}
443			if !confirmed {
444				return nil
445			}
446		}
447	
448		// Force mode - delete items
449		result, err := strategy.DeleteAllCleanupItems(ctx, items)
450		if err != nil {
451			return fmt.Errorf("failed to delete items: %w", err)
452		}
453	
454		// Delete temp files
455		deletedTempFiles, failedTempFiles := deleteTempFiles(ctx, tempFiles)
456	
457		// Report results
458		totalDeleted := len(result.ShadowBranches) + len(result.SessionStates) + len(result.Checkpoints) + len(result.V2Generations) + len(deletedTempFiles)
459		totalFailed := len(result.FailedBranches) + len(result.FailedStates) + len(result.FailedCheckpoints) + len(result.FailedV2Refs) + len(failedTempFiles)
460	
461		if totalDeleted > 0 {
462			fmt.Fprintf(w, "✓ Deleted %d %s:\n", totalDeleted, itemWord(totalDeleted))
463	
464			printResultSection(w, "Shadow branches", result.ShadowBranches)
465			printResultSection(w, "Session states", result.SessionStates)
466			printResultSection(w, "Checkpoints", result.Checkpoints)
467			printResultSection(w, "Archived v2 generations", result.V2Generations)
468	
469			printResultSection(w, "Temp files", deletedTempFiles)
470		}
471	
472		if totalFailed > 0 {
473			fmt.Fprintf(errW, "\nFailed to delete %d %s:\n", totalFailed, itemWord(totalFailed))
474	
475			printResultSection(errW, "Shadow branches", result.FailedBranches)
476			printResultSection(errW, "Session states", result.FailedStates)
477			printResultSection(errW, "Checkpoints", result.FailedCheckpoints)
478			printResultSection(errW, "Archived v2 generations", result.FailedV2Refs)
479	
480			if len(failedTempFiles) > 0 {
481				fmt.Fprintf(errW, "\nTemp files:\n")
482				for _, fe := range failedTempFiles {
483					fmt.Fprintf(errW, "  %s: %v\n", fe.File, fe.Err)
484				}
485			}
486	
487			return fmt.Errorf("failed to delete %d %s", totalFailed, itemWord(totalFailed))
488		}
489	
490		return nil
491	}
492	
493	// cleanupItemIDs extracts IDs from a slice of CleanupItems.
494	func cleanupItemIDs(items []strategy.CleanupItem) []string {
495		ids := make([]string, len(items))
496		for i, item := range items {
497			ids[i] = item.ID
498		}
