250	// DeleteOrphanedCheckpoints removes checkpoint directories from the entire/checkpoints/v1 branch.
251	func DeleteOrphanedCheckpoints(ctx context.Context, checkpointIDs []string) (deleted []string, failed []string, err error) {
252		if len(checkpointIDs) == 0 {
253			return []string{}, []string{}, nil
254		}
255	
256		repo, err := OpenRepository(ctx)
257		if err != nil {
258			return nil, nil, fmt.Errorf("failed to open git repository: %w", err)
259		}
260	
261		// Get sessions branch
262		refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
263		ref, err := repo.Reference(refName, true)
264		if err != nil {
265			return nil, nil, fmt.Errorf("sessions branch not found: %w", err)
266		}
267	
268		parentCommit, err := repo.CommitObject(ref.Hash())
269		if err != nil {
270			return nil, nil, fmt.Errorf("failed to get commit: %w", err)
271		}
272	
273		baseTree, err := parentCommit.Tree()
274		if err != nil {
275			return nil, nil, fmt.Errorf("failed to get tree: %w", err)
276		}
277	
278		// Flatten tree to entries
279		entries := make(map[string]object.TreeEntry)
280		if err := checkpoint.FlattenTree(repo, baseTree, "", entries); err != nil {
281			return nil, nil, fmt.Errorf("failed to flatten tree: %w", err)
282		}
283	
284		// Remove entries for each checkpoint
285		checkpointSet := make(map[string]bool)
286		for _, id := range checkpointIDs {
287			checkpointSet[id] = true
288		}
289	
290		// Find and remove entries matching checkpoint paths
291		for path := range entries {
292			for checkpointIDStr := range checkpointSet {
293				cpID, err := id.NewCheckpointID(checkpointIDStr)
294				if err != nil {
295					continue // Skip invalid checkpoint IDs
296				}
297				cpPath := cpID.Path()
298				if strings.HasPrefix(path, cpPath+"/") {
299					delete(entries, path)
300				}
301			}
302		}
303	
304		// Build new tree
305		newTreeHash, err := checkpoint.BuildTreeFromEntries(ctx, repo, entries)
306		if err != nil {
307			return nil, nil, fmt.Errorf("failed to build tree: %w", err)
308		}
309	
310		// Create commit
311		commit := &object.Commit{
312			Author: object.Signature{
313				Name:  "Entire CLI",
314				Email: "cli@entire.io",
315				When:  parentCommit.Author.When,
316			},
317			Committer: object.Signature{
318				Name:  "Entire CLI",
319				Email: "cli@entire.io",
320				When:  parentCommit.Committer.When,
321			},
322			Message:      fmt.Sprintf("Cleanup: removed %d orphaned checkpoints", len(checkpointIDs)),
323			TreeHash:     newTreeHash,
324			ParentHashes: []plumbing.Hash{ref.Hash()},
325		}
326	
327		obj := repo.Storer.NewEncodedObject()
328		if err := commit.Encode(obj); err != nil {
329			return nil, nil, fmt.Errorf("failed to encode commit: %w", err)
330		}
331	
332		commitHash, err := repo.Storer.SetEncodedObject(obj)
333		if err != nil {
334			return nil, nil, fmt.Errorf("failed to store commit: %w", err)
335		}
336	
337		// Update branch reference
338		newRef := plumbing.NewHashReference(refName, commitHash)
339		if err := repo.Storer.SetReference(newRef); err != nil {
340			return nil, nil, fmt.Errorf("failed to update branch: %w", err)
341		}
342	
343		// All checkpoints deleted successfully
344		return checkpointIDs, []string{}, nil
345	}
