347	// ListEligibleV2Generations returns archived checkpoints v2 /full/* generations
348	// eligible for deletion based on the configured retention window, along with
349	// warnings for malformed generations that were skipped.
350	func ListEligibleV2Generations(ctx context.Context, s *settings.EntireSettings) ([]CleanupItem, []string, error) {
351		repo, err := OpenRepository(ctx)
352		if err != nil {
353			return nil, nil, fmt.Errorf("failed to open git repository: %w", err)
354		}
355	
356		store := checkpoint.NewV2GitStore(repo, "origin")
357		candidates, tempRefs, warnings, err := listArchivedV2GenerationCandidates(ctx, repo, store)
358		if err != nil {
359			return nil, nil, fmt.Errorf("failed to list archived generations: %w", err)
360		}
361		defer removeTempRefs(repo, tempRefs)
362	
363		cutoff := time.Now().AddDate(0, 0, -s.GetFullTranscriptGenerationRetentionDays())
364		cleanupItems := make([]CleanupItem, 0, len(candidates))
365	
366		for _, candidate := range candidates {
367			if err := ctx.Err(); err != nil {
368				return nil, warnings, err //nolint:wrapcheck // propagate context.Canceled unwrapped so callers can detect it
369			}
370			commitHash, treeHash, refErr := store.GetRefState(candidate.RefName)
371			if refErr != nil {
372				warnings = append(warnings, fmt.Sprintf("generation %s: cannot read ref: %v", candidate.Name, refErr))
373				continue
374			}
375	
376			// Prefer the precomputed timestamps in generation.json — walking every
377			// checkpoint tree via go-git is expensive and generation.json (written
378			// at archive time and repaired by generation_repair.go) is the
379			// authoritative timestamp source in practice. The tree walk remains as
380			// a fallback for older generations whose generation.json is missing or
381			// incomplete.
382			gen, genErr := store.ReadGeneration(treeHash)
383			if genErr != nil || gen.OldestCheckpointAt.IsZero() || gen.NewestCheckpointAt.IsZero() {
384				var foundCheckpointTimes bool
385				var timestampErr error
386				gen, foundCheckpointTimes, timestampErr = store.ComputeGenerationTimestampsFromTrees(treeHash, nil)
387				if timestampErr != nil {
388					warnings = append(warnings, fmt.Sprintf("generation %s: failed to compute raw transcript timestamps: %v", candidate.Name, timestampErr))
389					continue
390				}
391				if !foundCheckpointTimes && genErr != nil {
392					warnings = append(warnings, fmt.Sprintf("generation %s: failed to read generation.json: %v", candidate.Name, genErr))
393					continue
394				}
395			}
396	
397			hasOldest := !gen.OldestCheckpointAt.IsZero()
398			hasNewest := !gen.NewestCheckpointAt.IsZero()
399			switch {
400			case !hasOldest && !hasNewest:
401				warnings = append(warnings, fmt.Sprintf("generation %s: missing generation.json", candidate.Name))
402				continue
403			case hasOldest != hasNewest:
404				warnings = append(warnings, fmt.Sprintf("generation %s: incomplete generation.json", candidate.Name))
405				continue
406			case gen.OldestCheckpointAt.After(gen.NewestCheckpointAt):
407				warnings = append(warnings, fmt.Sprintf("generation %s: invalid timestamps", candidate.Name))
408				continue
409			}
410			if !gen.NewestCheckpointAt.Before(cutoff) {
411				continue
412			}
413	
414			refOID := candidate.RefOID
415			if refOID == "" {
416				refOID = commitHash.String()
417			}
418			cleanupItems = append(cleanupItems, CleanupItem{
419				Type:   CleanupTypeV2Generation,
420				ID:     candidate.Name,
421				RefOID: refOID,
422				Reason: "expired archived full transcript generation",
423			})
424		}
425	
426		return cleanupItems, warnings, nil
427	}
428	
429	type archivedV2GenerationCandidate struct {
430		Name      string
431		RefName   plumbing.ReferenceName
432		RefOID    string
433		HasRemote bool
434	}
435	
436	func listArchivedV2GenerationCandidates(
437		ctx context.Context,
438		repo *git.Repository,
439		store *checkpoint.V2GitStore,
440	) ([]archivedV2GenerationCandidate, []plumbing.ReferenceName, []string, error) {
441		localNames, err := store.ListArchivedGenerations()
442		if err != nil {
443			return nil, nil, nil, fmt.Errorf("list local archived generations: %w", err)
444		}
445	
446		candidatesByName := make(map[string]archivedV2GenerationCandidate, len(localNames))
447		for _, name := range localNames {
448			refName := plumbing.ReferenceName(paths.V2FullRefPrefix + name)
449			ref, refErr := repo.Reference(refName, true)
450			if refErr != nil {
451				continue
452			}
453			candidatesByName[name] = archivedV2GenerationCandidate{
454				Name:    name,
455				RefName: refName,
456				RefOID:  ref.Hash().String(),
457			}
458		}
459	
460		var warnings []string
461		var tempRefs []plumbing.ReferenceName
462		target, targetErr := remote.FetchURL(ctx)
463		if targetErr == nil && target != "" {
464			remoteRefs, remoteErr := listRemoteArchivedV2GenerationRefs(ctx, target)
465			if remoteErr != nil {
466				warnings = append(warnings, fmt.Sprintf("failed to list remote v2 generations: %v", remoteErr))
467			} else {
468				fetchTarget, fetchTargetErr := remote.ResolveFetchTarget(ctx, target)
469				if fetchTargetErr != nil {
470					warnings = append(warnings, fmt.Sprintf("failed to resolve remote for v2 generation fetch: %v", fetchTargetErr))
471				} else {
472					for name, remoteOID := range remoteRefs {
473						if candidate, ok := candidatesByName[name]; ok {
474							if candidate.RefOID == remoteOID {
475								candidate.HasRemote = true
476								candidatesByName[name] = candidate
477								continue
478							}
479							warnings = append(warnings, fmt.Sprintf("generation %s: local archived ref OID %s differs from remote OID %s; skipping cleanup", name, candidate.RefOID, remoteOID))
480							delete(candidatesByName, name)
481							continue
482						}
483						tempRef, fetchErr := fetchArchivedV2Generation(ctx, fetchTarget, name)
484						if fetchErr != nil {
485							warnings = append(warnings, fmt.Sprintf("generation %s: failed to fetch remote ref: %v", name, fetchErr))
486							continue
487						}
488						tempRefs = append(tempRefs, tempRef)
489						candidatesByName[name] = archivedV2GenerationCandidate{
490							Name:      name,
491							RefName:   tempRef,
492							RefOID:    remoteOID,
493							HasRemote: true,
494						}
495					}
496				}
497			}
498		}
499	
500		names := make([]string, 0, len(candidatesByName))
501		for name := range candidatesByName {
502			names = append(names, name)
503		}
504		sort.Strings(names)
505	
506		candidates := make([]archivedV2GenerationCandidate, 0, len(names))
507		for _, name := range names {
508			candidates = append(candidates, candidatesByName[name])
509		}
510		return candidates, tempRefs, warnings, nil
511	}
512	
513	func listRemoteArchivedV2GenerationRefs(ctx context.Context, target string) (map[string]string, error) {
514		output, err := remote.LsRemote(ctx, target, paths.V2FullRefPrefix+"*")
515		if err != nil {
516			return nil, fmt.Errorf("ls remote v2 generations: %w", err)
517		}
518	
519		refs := make(map[string]string)
520		for line := range strings.SplitSeq(strings.TrimSpace(string(output)), "\n") {
521			if line == "" {
522				continue
523			}
524			parts := strings.Fields(line)
525			if len(parts) < 2 {
526				continue
527			}
528			refName := parts[1]
529			suffix := strings.TrimPrefix(refName, paths.V2FullRefPrefix)
530			if suffix == "current" || !checkpoint.GenerationRefPattern.MatchString(suffix) {
531				continue
532			}
533			refs[suffix] = parts[0]
534		}
535		return refs, nil
536	}
537	
538	func fetchArchivedV2Generation(ctx context.Context, fetchTarget, name string) (plumbing.ReferenceName, error) {
539		refName := paths.V2FullRefPrefix + name
540		tempRef := plumbing.ReferenceName("refs/entire-clean-tmp/v2/full/" + name)
541		refSpec := fmt.Sprintf("+%s:%s", refName, tempRef)
542		if output, err := remote.Fetch(ctx, remote.FetchOptions{
543			Remote:   fetchTarget,
544			RefSpecs: []string{refSpec},
545			NoTags:   true,
546			NoFilter: true,
547		}); err != nil {
548			return "", fmt.Errorf("%s: %w", strings.TrimSpace(string(output)), err)
549		}
550		return tempRef, nil
551	}
