559	// V2GenerationRef pairs a generation name with the OID observed at listing time.
560	type V2GenerationRef struct {
561		Name   string
562		RefOID string // Commit hash for compare-and-swap; empty skips the check
563	}
564	
565	// DeleteV2Generations deletes archived checkpoints v2 /full/* generation refs.
566	// When RefOID is set, deletion uses compare-and-swap to avoid deleting a ref
567	// that was repointed after enumeration.
568	func DeleteV2Generations(ctx context.Context, generations []V2GenerationRef) (deleted []string, failed []string, err error) { //nolint:unparam // err kept for consistency with other Delete* functions
569		if len(generations) == 0 {
570			return []string{}, []string{}, nil
571		}
572	
573		pushTarget, _, pushTargetErr := remote.PushURL(ctx, "origin")
574	
575		for _, gen := range generations {
576			refName := plumbing.ReferenceName(paths.V2FullRefPrefix + gen.Name)
577			localErr := DeleteRefCLI(ctx, refName.String(), gen.RefOID)
578			if errors.Is(localErr, ErrRefNotFound) {
579				localErr = nil
580			}
581			if localErr != nil {
582				failed = append(failed, gen.Name)
583				continue
584			}
585			if pushTargetErr == nil && pushTarget != "" {
586				if remoteErr := deleteRemoteRef(ctx, pushTarget, refName.String(), gen.RefOID); remoteErr != nil {
587					failed = append(failed, gen.Name)
588					continue
589				}
590			}
591			deleted = append(deleted, gen.Name)
592		}
593	
594		return deleted, failed, nil
595	}
596	
597	func deleteRemoteRef(ctx context.Context, target, refName, expectedOID string) error {
598		return pushWithLease(ctx, target, ":"+refName, refName, expectedOID,
599			"delete remote ref "+refName)
600	}
601	
602	// pushWithLease runs `git push <target> <refSpec>` with an optional
603	// `--force-with-lease=<leaseRef>:<expectedOID>` guard. errCtx prefixes the
604	// error message when no stderr output is available from the push.
605	func pushWithLease(ctx context.Context, target, refSpec, leaseRef, expectedOID, errCtx string) error {
606		extraArgs := []string{}
607		if expectedOID != "" {
608			extraArgs = append(extraArgs, fmt.Sprintf("--force-with-lease=%s:%s", leaseRef, expectedOID))
609		}
610		result, err := remote.PushWithOptions(ctx, remote.PushOptions{
611			Remote:    target,
612			RefSpecs:  []string{refSpec},
613			ExtraArgs: extraArgs,
614		})
615		if err != nil {
616			output := strings.TrimSpace(result.Output)
617			if output != "" {
618				return fmt.Errorf("%s: %w", output, err)
619			}
620			return fmt.Errorf("%s: %w", errCtx, err)
621		}
622		return nil
623	}
624	
625	// ListAllItems returns all Entire items for full cleanup.
626	// This includes all shadow branches and all session states regardless of
627	// whether they have checkpoints or active shadow branches.
628	func ListAllItems(ctx context.Context) ([]CleanupItem, error) {
629		var cleanupItems []CleanupItem
630	
631		// All shadow branches (using ListShadowBranches directly, not
632		// ListOrphanedItems, so this won't break if orphan filtering is added)
633		branches, err := ListShadowBranches(ctx)
634		if err != nil {
635			return nil, fmt.Errorf("listing shadow branches: %w", err)
636		}
637		for _, branch := range branches {
638			cleanupItems = append(cleanupItems, CleanupItem{
639				Type:   CleanupTypeShadowBranch,
640				ID:     branch,
641				Reason: "clean all",
642			})
643		}
644	
645		// All session states (not just orphaned)
646		store, err := session.NewStateStore(ctx)
647		if err != nil {
648			return nil, fmt.Errorf("failed to create state store: %w", err)
649		}
650	
651		states, err := store.List(ctx)
652		if err != nil {
653			return nil, fmt.Errorf("failed to list session states: %w", err)
654		}
655	
656		for _, state := range states {
657			cleanupItems = append(cleanupItems, CleanupItem{
658				Type:   CleanupTypeSessionState,
659				ID:     state.SessionID,
660				Reason: "clean all",
661			})
662		}
663	
664		return cleanupItems, nil
665	}
666	
667	// DeleteAllCleanupItems deletes all specified cleanup items.
668	// Logs each deletion for audit purposes.
669	func DeleteAllCleanupItems(ctx context.Context, items []CleanupItem) (*CleanupResult, error) {
670		result := &CleanupResult{}
671		logCtx := logging.WithComponent(ctx, "cleanup")
672	
673		// Build ID-to-Reason map for logging after deletion
674		reasonMap := make(map[string]string)
675		for _, item := range items {
676			reasonMap[item.ID] = item.Reason
677		}
678	
679		// Group items by type
680		var branches, states, checkpoints []string
681		var v2Generations []V2GenerationRef
682		for _, item := range items {
683			switch item.Type {
684			case CleanupTypeShadowBranch:
685				branches = append(branches, item.ID)
686			case CleanupTypeSessionState:
687				states = append(states, item.ID)
688			case CleanupTypeCheckpoint:
689				checkpoints = append(checkpoints, item.ID)
690			case CleanupTypeV2Generation:
691				v2Generations = append(v2Generations, V2GenerationRef{Name: item.ID, RefOID: item.RefOID})
692			}
693		}
694	
695		// Delete shadow branches
696		if len(branches) > 0 {
697			deleted, failed, err := DeleteShadowBranches(ctx, branches)
698			if err != nil {
699				return result, err
700			}
701			result.ShadowBranches = deleted
702			result.FailedBranches = failed
703	
704			// Log deleted branches
705			for _, id := range deleted {
706				logging.Info(logCtx, "deleted shadow branch",
707					slog.String("type", string(CleanupTypeShadowBranch)),
708					slog.String("id", id),
709					slog.String("reason", reasonMap[id]),
710				)
711			}
712			// Log failed branches
713			for _, id := range failed {
714				logging.Warn(logCtx, "failed to delete shadow branch",
715					slog.String("type", string(CleanupTypeShadowBranch)),
716					slog.String("id", id),
717					slog.String("reason", reasonMap[id]),
718				)
719			}
720		}
721	
722		// Delete session states
723		if len(states) > 0 {
724			deleted, failed, err := DeleteOrphanedSessionStates(ctx, states)
725			if err != nil {
726				return result, err
727			}
728			result.SessionStates = deleted
729			result.FailedStates = failed
730	
731			// Log deleted session states
732			for _, id := range deleted {
733				logging.Info(logCtx, "deleted session state",
734					slog.String("type", string(CleanupTypeSessionState)),
735					slog.String("id", id),
736					slog.String("reason", reasonMap[id]),
737				)
738			}
739			// Log failed session states
740			for _, id := range failed {
741				logging.Warn(logCtx, "failed to delete session state",
742					slog.String("type", string(CleanupTypeSessionState)),
743					slog.String("id", id),
744					slog.String("reason", reasonMap[id]),
745				)
746			}
747		}
748	
749		// Delete checkpoints
750		if len(checkpoints) > 0 {
751			deleted, failed, err := DeleteOrphanedCheckpoints(ctx, checkpoints)
752			if err != nil {
753				return result, err
754			}
755			result.Checkpoints = deleted
756			result.FailedCheckpoints = failed
757	
758			// Log deleted checkpoints
759			for _, id := range deleted {
760				logging.Info(logCtx, "deleted checkpoint",
761					slog.String("type", string(CleanupTypeCheckpoint)),
762					slog.String("id", id),
763					slog.String("reason", reasonMap[id]),
764				)
765			}
766			// Log failed checkpoints
767			for _, id := range failed {
768				logging.Warn(logCtx, "failed to delete checkpoint",
769					slog.String("type", string(CleanupTypeCheckpoint)),
770					slog.String("id", id),
771					slog.String("reason", reasonMap[id]),
772				)
773			}
774		}
775	
776		if len(v2Generations) > 0 {
777			deleted, failed, err := DeleteV2Generations(ctx, v2Generations)
778			if err != nil {
779				return result, err
780			}
781			result.V2Generations = deleted
782			result.FailedV2Refs = failed
783	
784			for _, id := range deleted {
785				logging.Info(logCtx, "deleted v2 generation",
786					slog.String("type", string(CleanupTypeV2Generation)),
787					slog.String("id", id),
788					slog.String("reason", reasonMap[id]),
789				)
790			}
791			for _, id := range failed {
792				logging.Warn(logCtx, "failed to delete v2 generation",
793					slog.String("type", string(CleanupTypeV2Generation)),
794					slog.String("id", id),
795					slog.String("reason", reasonMap[id]),
796				)
797			}
798		}
799	
800		// Log summary
801		totalDeleted := len(result.ShadowBranches) + len(result.SessionStates) + len(result.Checkpoints) + len(result.V2Generations)
802		totalFailed := len(result.FailedBranches) + len(result.FailedStates) + len(result.FailedCheckpoints) + len(result.FailedV2Refs)
803		if totalDeleted > 0 || totalFailed > 0 {
804			logging.Info(logCtx, "cleanup completed",
805				slog.Int("deleted_branches", len(result.ShadowBranches)),
806				slog.Int("deleted_session_states", len(result.SessionStates)),
807				slog.Int("deleted_checkpoints", len(result.Checkpoints)),
808				slog.Int("deleted_v2_generations", len(result.V2Generations)),
809				slog.Int("failed_branches", len(result.FailedBranches)),
810				slog.Int("failed_session_states", len(result.FailedStates)),
811				slog.Int("failed_checkpoints", len(result.FailedCheckpoints)),
812				slog.Int("failed_v2_generations", len(result.FailedV2Refs)),
813			)
814		}
815	
816		return result, nil
817	}
818

